export interface Options {
    src: string;
    root: string;
}
export default class Archetypes {
    archetypes: Map<string, string | Archetype>;
    src: string;
    root: string;
    constructor(options: Options);
    register(name: string, archetype: string | Archetype): void;
    run(name: string | Archetype, args?: string[]): Promise<void>;
    save(file: ArchetypeFile | ArchetypeRemote): Promise<void>;
    load(name: string): Promise<Archetype>;
}
export type Archetype = (...args: string[]) => void | ArchetypeFile | ArchetypeRemote | Generator<ArchetypeFile | ArchetypeRemote> | AsyncGenerator<ArchetypeFile | ArchetypeRemote>;
/** To generate files dynamically */
export interface ArchetypeFile<T = unknown> {
    base?: "src" | "root";
    path: string;
    overwrite?: boolean;
    content: T | URL | ((prev?: T) => T | Promise<T>);
    url?: string;
}
/** Allow to download files */
export interface ArchetypeRemote {
    url: string | URL;
    path?: string;
    files: string[];
    overwrite?: boolean;
}
